#include <stdint.h>
#include <stdio.h>

/* Provided by the candidate in solution.c */
int cobs_decode(const uint8_t *enc, size_t enc_len, uint8_t *out);

int main(void)
{
    int enc_len;
    while (scanf("%d", &enc_len) == 1) {
        uint8_t enc[600];
        for (int i = 0; i < enc_len; i++) {
            unsigned int byte_value;
            if (scanf("%x", &byte_value) != 1) {
                return 1;
            }
            enc[i] = (uint8_t)byte_value;
        }

        uint8_t out[600];
        int n = cobs_decode(enc, (size_t)enc_len, out);
        if (n < 0) {
            printf("INVALID\n");
        } else {
            printf("%d", n);
            for (int i = 0; i < n; i++) {
                printf(" %02X", out[i]);
            }
            printf("\n");
        }
    }
    return 0;
}
